  "description": "按 material.list 返回的 attachmentId/representationId 回读已提取文本或原图，返回原件版本、表示版本与真实页/段落出处。文本分页不冒充全文；图片进入下一轮输入，准备好图片不表示模型已理解。原件尚未提取时明确提示 material.extract，不执行文件内容。",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": false,
    "properties": {
      "attachmentId": {
        "format": "uuid",
        "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
        "type": "string"
      },
      "maxChars": {
        "default": 6000,
        "maximum": 9007199254740991,
        "minimum": 1,
        "type": "integer"
      },
      "offset": {
        "default": 0,
        "maximum": 9007199254740991,
        "minimum": 0,
        "type": "integer"
      },
      "representationId": {
        "minLength": 1,
        "type": "string"
      }
    },
    "required": [
      "attachmentId",
      "representationId"
    ],
    "type": "object"
  },
  "invocation": "静态目录只说明已登记接口；当前运行是否可调用、文档范围、写权限、短句柄和服务配置，以宿主本轮发现与实际回执为准。",
  "manual": {
    "group": "read",
    "label": "读取材料",
    "targetKinds": []
  },
  "name": "material.read",
  "version": 1
}

