        ],
        "type": "object"
      },
      {
        "additionalProperties": false,
        "properties": {
          "detail": {
            "$ref": "#/$defs/__schema0"
          },
          "path": {
            "maxLength": 500,
            "minLength": 1,
            "type": "string"
          },
          "project": {
            "maxLength": 1000,
            "minLength": 1,
            "type": "string"
          },
          "purpose": {
            "$ref": "#/$defs/__schema1"
